#!/usr/bin/env node
// generated by multi-repo-ponytail-graft/v1; regenerate, do not hand-edit
//
// Repository-local Ponytail lifecycle hook launcher for Claude Code project
// settings. Runs the locked package's hook scripts with repo-scoped state, so
// mode and default-mode never leak into ~/.claude or ~/.config/ponytail.
const path = require('path');
const fs = require('fs');

const sidecarRoot = path.resolve(__dirname, '..');
const repoRoot = path.resolve(sidecarRoot, '..', '..');
const localModules = path.join(sidecarRoot, 'node_modules');

// Fixed allowlist: an unknown action must never become an arbitrary file load.
const ACTIONS = {
  activate: 'ponytail-activate.js',
  subagent: 'ponytail-subagent.js',
  track: 'ponytail-mode-tracker.js',
};

function die(msg) {
  process.stderr.write(`[ponytail-graft] ${msg}\n`);
  process.exit(1);
}

const action = process.argv[2];
if (!Object.prototype.hasOwnProperty.call(ACTIONS, action)) {
  die(`unknown ponytail hook action ${JSON.stringify(action)}; expected one of ${Object.keys(ACTIONS).join(', ')}.`);
}

// Strictly this sidecar's own copy: a direct path cannot walk up into a parent
// or sibling node_modules, and ponytail's `exports` map does not expose
// ./package.json, so require.resolve could not reach it anyway.
const pkgDir = path.join(localModules, '@dietrichgebert', 'ponytail');
if (!fs.existsSync(path.join(pkgDir, 'package.json'))) {
  die('@dietrichgebert/ponytail is not installed in this repository sidecar. Run: npm ci --prefix .agent-tools/ponytail-graft');
}

const hookFile = path.join(pkgDir, 'hooks', ACTIONS[action]);
if (!fs.existsSync(hookFile)) die(`locked ponytail package has no hooks/${ACTIONS[action]}.`);

// Per-repo state. getClaudeDir() honours CLAUDE_CONFIG_DIR, getConfigDir()
// honours XDG_CONFIG_HOME — both land inside this repo's ignored paths.
process.env.CLAUDE_CONFIG_DIR = path.join(repoRoot, '.claude');
process.env.XDG_CONFIG_HOME = path.join(sidecarRoot, 'state', 'config');

// Plugin-only host markers. ponytail-runtime.js switches its output schema and
// its state directory on these; a project hook must emit the native Claude
// shape, so they cannot be inherited from an outer process.
delete process.env.PLUGIN_DATA;
delete process.env.COPILOT_PLUGIN_DATA;
delete process.env.QODER_SESSION_ID;
delete process.env.CLAUDE_PLUGIN_ROOT;

require(hookFile);
